INSERT INTO quizquiz.bank_questions (id,category,difficulty,question,options,correct_answer_index,explanation,sources,status,provenance,review_note,reviewed_at) VALUES
('70000000-0000-4000-8000-000000000001','general','medium','국제단위계(SI)에서 물질량을 나타내는 기본 단위는 무엇일까요?',ARRAY['몰(mol)','켈빈(K)','칸델라(cd)','암페어(A)'],0,'몰은 물질량의 SI 기본 단위예요. 1몰에는 지정한 입자가 정확히 6.02214076 × 10²³개 들어 있어요.','[{"title": "NIST · SI 기본 단위", "url": "https://www.nist.gov/si-redefinition/definitions-si-base-units"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000002','general','hard','시간의 기본 단위인 초(s)를 정의할 때 기준으로 삼는 원자는 무엇일까요?',ARRAY['세슘-133','탄소-12','우라늄-235','수소-1'],0,'초는 세슘-133 원자의 특정 전이에 해당하는 주파수를 9,192,631,770 Hz로 고정해 정의해요.','[{"title": "NIST · SI 기본 단위", "url": "https://www.nist.gov/si-redefinition/definitions-si-base-units"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000003','science','medium','수성보다 태양에서 멀지만, 두꺼운 대기의 온실효과로 표면이 더 뜨거운 행성은?',ARRAY['금성','화성','목성','해왕성'],0,'금성의 두꺼운 이산화탄소 대기는 열을 가두어요. 금성은 태양계 행성 중 표면이 가장 뜨거워요.','[{"title": "NASA · 금성", "url": "https://science.nasa.gov/venus/venus-facts/"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000004','science','hard','천왕성 궤도의 예상 밖 움직임을 설명하려던 수학적 예측이 발견에 기여한 행성은?',ARRAY['해왕성','토성','금성','수성'],0,'해왕성의 중력이 천왕성의 궤도에 영향을 주었어요. 르베리에는 이 움직임을 토대로 미지 행성의 위치를 예측했어요.','[{"title": "NASA · 해왕성", "url": "https://science.nasa.gov/neptune/neptune-facts/"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000005','history','medium','유네스코가 현존하는 가장 오래된 금속활자 인쇄본으로 소개하는 책은?',ARRAY['직지심체요절','훈민정음 해례본','조선왕조실록','동의보감'],0,'직지심체요절은 현존하는 가장 오래된 금속활자 인쇄본으로 알려져 있어요. 유네스코 직지상도 이 기록유산의 이름을 따랐어요.','[{"title": "UNESCO · 직지상", "url": "https://www.unesco.org/en/prizes/jikji"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000006','history','easy','인류가 처음 달 표면에 착륙한 아폴로 11호의 임무는 몇 년에 이루어졌을까요?',ARRAY['1969년','1957년','1961년','1975년'],0,'아폴로 11호는 1969년 7월에 달에 착륙했어요. 닐 암스트롱과 버즈 올드린이 달 표면을 탐사했어요.','[{"title": "NASA · 아폴로 11호 임무", "url": "https://www.nasa.gov/missions/apollo/apollo-11/apollo-11-mission-overview/"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000007','geography','easy','지구에서 면적이 가장 넓은 대양은 어디일까요?',ARRAY['태평양','대서양','인도양','북극해'],0,'태평양은 지구에서 면적이 가장 넓고 가장 깊은 대양이에요.','[{"title": "NOAA · 태평양과 챌린저 해연", "url": "https://oceanexplorer.noaa.gov/ocean-fact/pacific-size/"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000008','geography','medium','바다에서 가장 깊은 곳으로 알려진 챌린저 해연은 어느 해구에 있을까요?',ARRAY['마리아나 해구','페루·칠레 해구','푸에르토리코 해구','자바 해구'],0,'챌린저 해연은 태평양의 마리아나 해구에 있어요. 해구는 해저에 길고 깊게 파인 지형이에요.','[{"title": "NOAA · 태평양과 챌린저 해연", "url": "https://oceanexplorer.noaa.gov/ocean-fact/pacific-size/"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000009','culture','medium','훈민정음 창제는 1443년이에요. 훈민정음 해례본이 간행되고 새 문자가 반포된 해는?',ARRAY['1446년','1392년','1592년','1894년'],0,'훈민정음은 1443년에 창제가 완료되었고 1446년에 반포되었어요. 해례본에는 문자의 원리와 사용 예가 담겨 있어요.','[{"title": "UNESCO · 훈민정음", "url": "https://www.unesco.org/en/memory-world/hunminjeongum-manuscript?hub=1081"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now()),
('70000000-0000-4000-8000-000000000010','culture','medium','탱고는 리오데라플라타 지역에서 발전했어요. 그 전통을 공유하는 두 나라는?',ARRAY['아르헨티나와 우루과이','스페인과 포르투갈','멕시코와 쿠바','브라질과 콜롬비아'],0,'탱고는 아르헨티나와 우루과이의 도시 문화에서 발전한 음악과 춤의 전통이에요.','[{"title": "UNESCO · 탱고", "url": "https://ich.unesco.org/en/RL/tango-00258"}]'::jsonb,'published','{"provider":"curated-sample","revision":"2026-10-06"}'::jsonb,'초기 샘플: 공식 출처와 정답·해설을 대조함. 난이도는 임시 분류.',now());
